export const SMOOTH_QUARTZ_SLAB = "smooth_quartz_slab";
export const SMOOTH_QUARTZ_STAIRS = "smooth_quartz_stairs";
export const SMOOTH_RED_SANDSTONE_STAIRS = "smooth_red_sandstone_stairs";
