// Shared vocabulary for the mid-century house (plan.md): palette constants, site coordinates, and one helper per
// plan.md VOCABULARY item. Helpers take the grid first, then plan.md's arguments, in WORLD coordinates (x east,
// y up with ground top = 0, bedding = -1, pool floor = -2, z = 0 the street). Every helper writes only through
// g.set, so runParts' ownership and palette reports apply. Shaped blocks come from the build library's B.* helpers.
import { B, DIRS, OPPOSITE } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

// ---- grid -----------------------------------------------------------------------------------------------------------
// The grid's index y is world y minus Y_ORIGIN: world y=-2 (the pool floor) is grid y=0, world y=8 (the chimney top)
// is grid y=10. Use GRID_SIZE for the build grid; x and z are world values unchanged.
export const Y_ORIGIN = -2;
export const GRID_SIZE = [34, 11, 34];
export const AIR = "minecraft:air";

// ---- palette (palette.json ids only) --------------------------------------------------------------------------------
export const ACACIA_DOOR = "acacia_door";
export const BARREL = "barrel";
export const BIRCH_PLANKS = "birch_planks";
export const BIRCH_SLAB = "birch_slab";
